//! Profile `crate-root/v1`: the Bazel package and the crate root of a `v2` model.

use crate::plan::{Artifact, Ownership};
use crate::text;
use crate::v2::Gen;
use crate::{PlanError, planned_path};

/// Profile name recorded for crate-level files.
pub const PROFILE: &str = "crate-root/v1";

pub fn artifacts(generator: &Gen<'_>) -> Result<Vec<Artifact>, PlanError> {
    Ok(vec![build_file(generator)?, lib_rs(generator)?])
}

fn build_file(generator: &Gen<'_>) -> Result<Artifact, PlanError> {
    let krate = &generator.model.system.rust_crate;
    let content = format!(
        "# @generated by L2R ({PROFILE}). Do not edit: change the architecture model,\n\
         # then re-plan, re-approve and regenerate.\n\
         load(\"@rules_rust//rust:defs.bzl\", \"rust_library\", \"rust_test\")\n\
         \n\
         rust_library(\n    \
             name = \"{krate}\",\n    \
             srcs = glob([\"src/**/*.rs\"]),\n    \
             crate_root = \"src/lib.rs\",\n    \
             edition = \"2024\",\n    \
             visibility = [\"//visibility:public\"],\n\
         )\n\
         \n\
         rust_test(\n    \
             name = \"{krate}_test\",\n    \
             crate = \":{krate}\",\n    \
             edition = \"2024\",\n\
         )\n\
         \n\
         # Every file in this package, so that drift checks can compare it with the plan.\n\
         filegroup(\n    \
             name = \"l2r_files\",\n    \
             srcs = glob([\"**\"]),\n    \
             visibility = [\"//visibility:public\"],\n\
         )\n"
    );
    Ok(Artifact {
        path: planned_path("BUILD.bazel".into())?,
        ownership: Ownership::Generated,
        profile: PROFILE.into(),
        purpose: "Bazel package building the generated crate and its contract tests".into(),
        components: vec![generator.root.id.clone()],
        lean: vec![],
        content,
    })
}

fn lib_rs(generator: &Gen<'_>) -> Result<Artifact, PlanError> {
    let model = generator.model;
    let summary = format!(
        "{} — Rust scaffold generated by L2R from the architecture model `{}`.\n\
         \n\
         Module layout, types and contracts are fixed by the approved generation plan.\n\
         `types` mirrors the Lean data types, one Rust type per Lean type. Behavior is\n\
         implemented in the `imp.rs` and `routes.rs` files, which L2R creates once and\n\
         never overwrites.",
        model.system.name, model.system.id
    );
    let mut modules = [generator.root.rust_module.as_str(), "types"];
    modules.sort();
    let content = format!(
        "{}\n{}\n#![forbid(unsafe_code)]\n\npub mod {};\npub mod {};\n",
        text::generated_marker(PROFILE),
        text::inner_doc(&summary),
        modules[0],
        modules[1],
    );
    Ok(Artifact {
        path: planned_path("src/lib.rs".into())?,
        ownership: Ownership::Generated,
        profile: PROFILE.into(),
        purpose: "Crate root".into(),
        components: vec![generator.root.id.clone()],
        lean: vec![],
        content,
    })
}
